// === Tab: mySketch ===
const TEXTURE_SIZE = 128;
const SIZE = TEXTURE_SIZE*2
const PARTICLE_COUNT = TEXTURE_SIZE * TEXTURE_SIZE;

let indices = new Float32Array(PARTICLE_COUNT);
let particleGeom;

let fontLoaded = false;

let simulationShader;
let renderShader;
let next;
let prev;
let topLeft;
let bottomRight;
let up;
let down;
let left;
let right;
let size;

const simVert = `
precision highp float;

attribute vec3 aPosition;
attribute vec2 aTexCoord;
attribute vec4 aVertexColor;

uniform mat4 uModelViewMatrix;
uniform mat4 uProjectionMatrix;
varying vec2 vTexCoord;


void main() {
  vec4 viewModelPosition = uModelViewMatrix * vec4(aPosition, 1.0);
  gl_Position = uProjectionMatrix * viewModelPosition;

  // gl_Position = vec4(aPosition.xy, 0.0, 1.0);

  // vTexCoord =  (vTexCoord.xy) * 2.0;
  vTexCoord = aTexCoord.xy  ;

}`

const simFrag = `
precision highp float;

uniform sampler2D u_particles;
uniform float u_dt;

varying vec2 vTexCoord;

void main() {

    vec4 particule = texture2D(u_particles, vTexCoord);

    vec2 position = particule.xy;
    vec2 velocity = particule.zw;


    vec2 acceleration = vec2(cos(vTexCoord.x), sin(vTexCoord.y));
    velocity += acceleration * u_dt;
    position += velocity * u_dt;
    position = fract(position);

    gl_FragColor = vec4(position, velocity);
 //  gl_FragColor = vec4(particule.x,particule.y, 0.0, 1);
}`

const renderVert = `
attribute float aIndex;
uniform sampler2D u_particles;
uniform float u_texSize;

void main() {
    float x = mod(aIndex, u_texSize) / u_texSize;
    float y = floor(aIndex / u_texSize) / u_texSize;

    vec2 uv = vec2(x, y);
    vec4 p = texture2D(u_particles, uv);

    vec2 position = p.xy;

    gl_Position = vec4(position, 0.0, 1.0);
    gl_PointSize = 2.0;
}`

const renderFrag = `
precision highp float;

void main() {
  // gl_PointCoord ∈ [0,1] inside the point
  vec2 uv = gl_PointCoord * 2.0 - 1.0;
  float d = dot(uv, uv);

  if (d > 1.0) discard;

  float alpha = 1.0 - d;
  gl_FragColor = vec4(1.0, 0.7, 0.2, alpha);
}`

function preload() {
  simulationShader = createShader(simVert, simFrag);
  renderShader = createShader(renderVert, renderFrag);
}

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  frameRate(30)

  zoom = max(windowWidth, windowHeight) / TEXTURE_SIZE
  // Init coordinat
  up = -TEXTURE_SIZE*zoom / 2;
  left = -TEXTURE_SIZE*zoom / 2;
  down = TEXTURE_SIZE*zoom / 2;
  right = TEXTURE_SIZE*zoom / 2;

  //Init indices
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    indices[i] = i;
  }

  // Init particles geometrie
  particleGeom = new p5.Geometry();
  for (let i = 0; i < PARTICLE_COUNT; i++) {
    particleGeom.vertices.push([0, 0, 0]);
  }
  particleGeom.computeNormals();
  particleGeom.vertexBuffers = {
    aIndex: {
      data: indices, // expose vertex indexes
      size: 1,
    },
  };
  particleGeom.drawMode = POINTS;

  // Init Simulation texture
  next = createFramebuffer({
    width: TEXTURE_SIZE,
    height: TEXTURE_SIZE,
    format: FLOAT,
  });

  prev = createFramebuffer({
    width: TEXTURE_SIZE,
    height: TEXTURE_SIZE,
    format: FLOAT,
  });

  next.begin();
  for (let y = 0; y < TEXTURE_SIZE; y++) {
    for (let x = 0; x < TEXTURE_SIZE; x++) {
      stroke(
        random(255), // pos.x
        random(255), // pos.y
        0.0, // vel.x
        255.0 // vel.y
      );
      point(x, y);
    }
  }
  next.end();
  image(next, 0, 0);
}


function draw() {
  [prev, next] = [next, prev];

  next.begin();

  clear();
  shader(simulationShader);
  simulationShader.setUniform("u_dt", 0.005);
  simulationShader.setUniform("u_particles", prev);
  noStroke();
  plane(TEXTURE_SIZE, TEXTURE_SIZE);
  resetShader();

  next.end();

  image(next, left, up ,TEXTURE_SIZE*zoom, TEXTURE_SIZE*zoom);
}

